l","affiliation":[],"role":[{"role":"author","vocabulary":"crossref"}]},{"given":"Sirish","family":"L.","sequence":"additional","affiliation":[],"role":[{"role":"author","vocabulary":"crossref"}]}],"member":"3774","published-online":{"date-parts":[[2010,3,1]]},"container-title":["Fault Detection"],"language":"en","link":[{"URL":"https://www.intechopen.com/download/pdf/10368","content-type":"unspecified","content-version":"vor","intended-application":"similarity-checking"}],"deposited":{"date-parts":[[2017,3,31]],"date-time":"2017-03-31T05:50:14Z","timestamp":1490939414000},"score":29.976578,"resource":{"primary":{"URL":"http://www.intechopen.com/books/fault-detection/qualitative-fault-detection-and-hazard-analysis-based-on-signed-directed-graphs-for-large-scale-comp"}},"issued":{"date-parts":[[2010,3,1]]},"ISBN":["9789533070377"],"references-count":0,"URL":"https://doi.org/10.5772/9077","published":{"date-parts":[[2010,3,1]]}},{"indexed":{"date-parts":[[2025,12,18]],"date-time":"2025-12-18T18:55:05Z","timestamp":1766084105392,"version":"3.48.0"},"publisher":"Publications Office of the European Union","award-start":{"date-parts":[[2023,2,1]]},"award":"101100615","DOI":"10.3030/101100615","type":"grant","created":{"date-parts":[[2022,12,12]],"date-time":"2022-12-12T10:35:31Z","timestamp":1670841331000},"source":"Crossref","prefix":"10.3030","member":"4854","project":[{"project-title":[{"title":"efficient Syntactic Analysis for Large-scale Sentiment Analysis","language":"en"},{"title":"SALSA","language":"en"}],"project-description":[{"description":"One of the key aspects of any successful business is knowing how customers feel about its brand and products. For this purpose, sentiment analysis or opinion mining tools could be paramount in helping companies to succeed. However, the current state of the art sentiment analysis solutions (both commercial or academic) present important drawbacks including low accuracy, low performance (response time around 100-1000 ms), high computational cost and/or high price (around €500/month on average) relegating these solutions to consolidated big brands, social listening agencies or consulting firms offering social listening services.

SALSA aims to democratize the analysis and transformation of internet/social data into knowledge creation for decision-makers, making large-scale sentiment analysis technology viable for small entities without massive computational power. SALSA will explore the potential of the powerful models and algorithms developed within ERC Starting Grant FASTPARSE to create the first AI-based syntax-guided sentiment analysis engine which is: a) accurate, due to using syntactic information to infer the opinions contained in each sentence from its structure and the relationship between its words, rather than shallow methods that consider words in isolation and b) cost-effective, due to employing fast parsers that have a throughput in the order of 1000 sentences per second on consumer-grade hardware, and that can work without time- and memory-hungry large language models.

SALSA will follow an open-source software business model in which we will explore several sources of revenue, most based  on service-level agreement. This will highly contribute to the competitiveness of the EU technological market by reducing their dependency on the oligopoly of technological giants (mostly American and Chinese) that currently have a dominant position in language technologies, largely thanks to their enormous computational resources.","language":"en"}],"award-amount":{"amount":150000.0,"currency":"EUR"},"award-start":{"date-parts":[[2023,2,1]]},"funding":[{"type":"grant","scheme":"HORIZON.1.1","award-amount":{"amount":150000.0,"currency":"EUR","percentage":100},"funder":{"id":[{"id":"10.13039/100019180","id-type":"DOI","asserted-by":"publisher"}],"name":"HORIZON EUROPE HORIZON.1.1"}}]}],"deposited":{"date-parts":[[2025,12,18]],"date-time":"2025-12-18T18:38:17Z","timestamp":1766083097000},"score":29.087524,"resource":{"primary":{"URL":"https://cordis.europa.eu/project/id/101100615"}},"issued":{"date-parts":[[2023,2,1]]},"URL":"https://doi.org/10.3030/101100615"}],"items-per-page":3,"query":{"start-index":0,"search-terms":null}}}
